<?php
declare(strict_types=1);
use NpmGateway\Container\ServiceProvider;
use NpmGateway\Database\DatabaseProfiles;
use NpmGateway\Database\MySqlConnectionFactory;
use NpmGateway\Services\PropertyQueryService;
use NpmGateway\ValueObjects\PropertyDirectoryCriteria;
$application=require dirname(__DIR__,2).'/bootstrap/app.php';$db=MySqlConnectionFactory::connect(DatabaseProfiles::load('migration',$application['root']));$row=$db->query("SELECT prop_id,property_code,slug,display_name,status,address_line_1,city,state,postal_code,timezone,office_phone,manager_email,website_url,ivr_number,ivr_routing_email FROM properties WHERE prop_id=1 AND property_code='CO' AND slug='corporate'")->fetch_assoc();$audit=(int)$db->query("SELECT COUNT(*) FROM audit_logs WHERE event_type='system.corporate_context_created'")->fetch_row()[0];$db->close();if(!is_array($row))throw new RuntimeException('Corporate context is missing.');$expected=['prop_id'=>'1','property_code'=>'CO','slug'=>'corporate','display_name'=>'Corporate','status'=>'active','address_line_1'=>'5021 River Rd., Ste. C','city'=>'Columbus','state'=>'GA','postal_code'=>'31904','timezone'=>'America/New_York','office_phone'=>'+17065874386','manager_email'=>'noc@npmparks.com','website_url'=>'https://npmpropertiesinc.com','ivr_number'=>null,'ivr_routing_email'=>null];foreach($expected as $key=>$value)if($row[$key]!==$value)throw new RuntimeException("Unexpected Corporate value: {$key}");$container=ServiceProvider::build($application);$page=$container->get(PropertyQueryService::class)->search(new PropertyDirectoryCriteria());$match=array_values(array_filter($page->properties,static fn($property):bool=>$property->propId===1));if(count($match)!==1)throw new RuntimeException('Corporate directory row is missing or duplicated.');$display=$match[0];foreach(['address'=>'5021 River Rd., Ste. C, Columbus, GA 31904','phone'=>'(706) 587-4386','ivr'=>'—','manager'=>'Not assigned'] as $key=>$value)if($display->{$key}!==$value)throw new RuntimeException("Unexpected Corporate directory value: {$key}");$container->get(mysqli::class)->close();echo 'Corporate record and directory display verified; audit events='.$audit.PHP_EOL;
